<?php require '../common.php'; startpage('Issue Book');nav('<a href="index.php">Catalog</a>');$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT * FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();$b=$s->get_result()->fetch_assoc();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$b){$student=trim($_POST['student']);$issue=date('Y-m-d');$due=date('Y-m-d',strtotime('+14 days'));if($student&&$b['available']>0){$s=$conn->prepare('INSERT INTO loans(student,book_id,issue_date,due_date) VALUES(?,?,?,?)');$s->bind_param('siss',$student,$id,$issue,$due);$s->execute();$conn->query("UPDATE books SET available=available-1 WHERE id=$id");$msg='Book issued. Due date: '.$due;}else $msg='Book unavailable or name missing.';}
if($b):?><form method="post"><p>Book: <?=e($b['title'])?></p><input name="student" placeholder="Student name" required><button>Issue for 14 days</button></form><?php endif;if($msg)echo '<p class="msg">'.e($msg).'</p>';endpage();?>